create table depositos (id int primary key, nombre text not null, zona text not null);
insert into depositos values
 (1,'Retiro','Norte'),(2,'Palermo','Norte'),(3,'Belgrano','Norte'),(4,'San Isidro','Norte'),
 (5,'Barracas','Sur'),(6,'Avellaneda','Sur'),(7,'Lanús','Sur'),(8,'Quilmes','Sur'),
 (9,'Flores','Oeste'),(10,'Haedo','Oeste'),(11,'Morón','Oeste'),(12,'Ituzaingó','Oeste');

create table bultos (
  id bigint primary key, deposito_id int not null, estado text not null,
  peso_kg int not null, creado timestamp not null);
insert into bultos                                   -- 300.000 bultos, sin azar
select g, 1 + (g * 7919) % 12,
       (array['en_deposito','en_ruta','entregado','entregado','entregado','entregado','devuelto'])[1 + (g * 31) % 7],
       1 + (g * 17) % 40, timestamp '2026-01-01' + g * interval '2 minutes'
from generate_series(1::bigint, 300000) g;

create table eventos (id bigint primary key, bulto_id bigint not null, tipo text not null, cuando timestamp not null);
insert into eventos                                  -- 2 eventos por bulto: ingreso y salida
select g, 1 + (g - 1) % 300000, case when g <= 300000 then 'ingreso' else 'salida' end,
       timestamp '2026-01-01' + g * interval '1 minute'
from generate_series(1::bigint, 600000) g;
create index eventos_bulto on eventos (bulto_id);
vacuum analyze;

